/*
 * test_boot_logo.c -- the boot-screen logo STRIKE oracle (bead initech-tdnl.105).
 *
 * Ref: pubs/common/initech-logo.tex (the TikZ drawing), docs/pubs/
 *      DESIGN-REFERENCE.md Sec 7.0 (the measured geometry), spec/assets/
 *      boot_logo.h (the strike under test, generated by tools/boot_logo_gen.c).
 *      CLAUDE.md Law 2 (independent oracle), Rule 6 (mutation-proven),
 *      Rule 12 (ASCII).
 *
 * WHAT IT PROVES: the shipped strike equals the logo geometry, pixel for pixel.
 * The expectation is computed HERE from this file's own transcription of the
 * TikZ parameters, by a PER-PIXEL renderer (crossing-number point-in-polygon
 * for the block faces and the six straight-sided letters, an ANALYTIC test --
 * outer ellipse minus counter minus mouth -- for the C). It never reads the
 * strike to form the expectation; the generator fills by scanline spans over a
 * polygonised C, so a transcription slip on either side shows as a pixel diff.
 * It also refuses a raster in which a pixel centre sits within 1e-6 px of an
 * edge (two correct renderers could round such a tie differently).
 *
 * MUTANT (Rule 6): -DBOOT_LOGO_MUT_NOTCH_ROW moves the back block's notch
 * floor up by one row in the decoded strike (the first floor row takes the row
 * above it). The comparison MUST go RED.
 */
#include <math.h>
#include <stdio.h>
#include <string.h>

#include "boot_logo.h"          /* the strike under test (-Ispec/assets) */
#include "test_assert.h"        /* TEST_HARNESS / CHECK / TEST_SUMMARY (-Iseed) */

TEST_HARNESS();

#define LW 15.264               /* lockup width (u)                       */
#define LH 10.459               /* lockup height (u), baseline to apex    */
#define SL 0.207                /* logotype xslant                        */
#define MX 7.632                /* the mark's shift inside the lockup     */
#define MY 8.010

static double ox, oy, near_tie = 1e9;
static unsigned char want[256][256], got[256][256];

typedef struct { double x, y; } pt;

/* Crossing number for one pixel centre; records the nearest crossing. */
static int inside(const pt *v, int n, double px, double py)
{
    int in = 0;
    for (int a = 0, b = n - 1; a < n; b = a++) {
        if ((v[a].y > py) != (v[b].y > py)) {
            double xc = v[b].x + (py - v[b].y) * (v[a].x - v[b].x) / (v[a].y - v[b].y);
            if (fabs(xc - px) < near_tie) near_tie = fabs(xc - px);
            if (px < xc) in = !in;
        }
    }
    return in;
}

static void paint_poly(const double (*c)[2], int n, double sx, double sy,
                       double slant, int code)
{
    pt v[16];
    for (int k = 0; k < n; k++) {
        double X = c[k][0] + sx + slant * (c[k][1] + sy), Y = c[k][1] + sy;
        v[k].x = ox + X * BOOT_LOGO_U;
        v[k].y = oy + (LH - Y) * BOOT_LOGO_U;
    }
    for (int j = 0; j < BOOT_LOGO_H; j++)
        for (int i = 0; i < BOOT_LOGO_W; i++)
            if (inside(v, n, i + 0.5, j + 0.5)) want[j][i] = (unsigned char)code;
}

/* Signed margin of (x,y) against an ellipse: <0 inside, >0 outside. */
static double ell(double x, double y, double cx, double cy, double rx, double ry)
{
    double dx = (x - cx) / rx, dy = (y - cy) / ry;
    return dx * dx + dy * dy - 1.0;
}

/* The C, analytically: inside the outer ellipse, outside the counter (four
 * quarter ellipses and the straight left side) and outside the mouth band to
 * the right of the terminals. Upright coordinates (the shear is undone). */
static int in_c(double x, double y)
{
    double m = ell(x, y, 10.908, 1.272, 1.209, 1.304);
    if (fabs(m) < near_tie) near_tie = fabs(m);
    if (m >= 0.0) return 0;
    if (x > 11.385 && y > 0.986 && y < 1.622) return 0;          /* mouth   */
    if (x <= 10.908) {                                            /* counter */
        double t = (x - 10.908) / 0.413;
        if (t < -1.0) return 1;
        double s = sqrt(1.0 - t * t);
        double lo = 1.018 - 0.382 * s, hi = 1.590 + 0.334 * s;
        return !(y > lo && y < hi);
    } else {
        double t = (x - 10.908) / 0.477;
        if (t > 1.0) return 1;
        double s = sqrt(1.0 - t * t);
        double lo = 0.986 - 0.350 * s, hi = 1.622 + 0.302 * s;
        return !(y > lo && y < hi);
    }
}

static void render_geometry(void)
{
    static const double L1[6][2] = {{2,-1},{0,-2},{0,-0.775},{1,-0.275},{1,0.949},{2,1.449}};
    static const double L2[4][2] = {{0,0.225},{-1,-0.275},{-1,0.949},{0,1.449}};
    static const double D1[6][2] = {{-2,-1},{0,-2},{0,-0.775},{-1,-0.275},{-1,0.949},{-2,1.449}};
    static const double D2[4][2] = {{0,0.225},{1,-0.275},{1,0.949},{0,1.449}};
    static const double T1[6][2] = {{0,2.449},{2,1.449},{1,0.949},{0,1.449},{-1,0.949},{-2,1.449}};
    static const double T2[4][2] = {{0,0.225},{1,-0.275},{0,-0.775},{-1,-0.275}};
    static const double bs[3][2] = {{0,0},{-2.5,-2},{2.5,-2}};
    static const double I1[4][2] = {{0,0},{0.763,0},{0.763,2.536},{0,2.536}};
    static const double N1[10][2] = {{1.161,0},{1.908,0},{1.908,1.407},{2.668,0},{3.435,0},
        {3.435,2.536},{2.687,2.536},{2.687,1.145},{1.956,2.536},{1.161,2.536}};
    static const double I2[4][2] = {{3.848,0},{4.611,0},{4.611,2.536},{3.848,2.536}};
    static const double T3[8][2] = {{5.549,0},{6.325,0},{6.325,1.884},{7.025,1.884},
        {7.025,2.536},{4.863,2.536},{4.863,1.884},{5.549,1.884}};
    static const double E1[12][2] = {{7.314,0},{9.413,0},{9.413,0.660},{8.078,0.660},
        {8.078,0.986},{9.286,0.986},{9.286,1.582},{8.078,1.582},{8.078,1.884},
        {9.398,1.884},{9.398,2.536},{7.314,2.536}};
    static const double H1[12][2] = {{12.482,0},{13.246,0},{13.246,1.018},{13.961,1.018},
        {13.961,0},{14.740,0},{14.740,2.536},{13.961,2.536},{13.961,1.654},
        {13.246,1.654},{13.246,2.536},{12.482,2.536}};

    memset(want, BOOT_LOGO_CODE_CLEAR, sizeof want);
    for (int b = 0; b < 3; b++) {
        double sx = MX + bs[b][0], sy = MY + bs[b][1];
        paint_poly(L1, 6, sx, sy, 0.0, BOOT_LOGO_CODE_LIGHT);
        paint_poly(L2, 4, sx, sy, 0.0, BOOT_LOGO_CODE_LIGHT);
        paint_poly(D1, 6, sx, sy, 0.0, BOOT_LOGO_CODE_DARK);
        paint_poly(D2, 4, sx, sy, 0.0, BOOT_LOGO_CODE_DARK);
        paint_poly(T1, 6, sx, sy, 0.0, BOOT_LOGO_CODE_TOP);
        paint_poly(T2, 4, sx, sy, 0.0, BOOT_LOGO_CODE_TOP);
    }
    paint_poly(I1, 4, 0, 0, SL, BOOT_LOGO_CODE_DARK);
    paint_poly(N1, 10, 0, 0, SL, BOOT_LOGO_CODE_DARK);
    paint_poly(I2, 4, 0, 0, SL, BOOT_LOGO_CODE_DARK);
    paint_poly(T3, 8, 0, 0, SL, BOOT_LOGO_CODE_DARK);
    paint_poly(E1, 12, 0, 0, SL, BOOT_LOGO_CODE_DARK);
    for (int j = 0; j < BOOT_LOGO_H; j++) {
        for (int i = 0; i < BOOT_LOGO_W; i++) {
            double Y = LH - (j + 0.5 - oy) / BOOT_LOGO_U;
            double X = (i + 0.5 - ox) / BOOT_LOGO_U;
            if (in_c(X - SL * Y, Y)) want[j][i] = BOOT_LOGO_CODE_DARK;
        }
    }
    paint_poly(H1, 12, 0, 0, SL, BOOT_LOGO_CODE_DARK);
}

static int decode_strike(void)
{
    int k = 0;
    for (int j = 0; j < BOOT_LOGO_H; j++) {
        int i = 0;
        while (i < BOOT_LOGO_W) {
            if (k >= BOOT_LOGO_RLE_BYTES) return 0;
            int code = boot_logo_rle[k] >> 6, len = (boot_logo_rle[k] & 63) + 1;
            k++;
            if (i + len > BOOT_LOGO_W) return 0;
            memset(&got[j][i], code, (size_t)len);
            i += len;
        }
    }
    return k == BOOT_LOGO_RLE_BYTES;
}

int main(void)
{
    printf("test-boot-logo: strike == independent re-render of the TikZ geometry\n");

    CHECK(BOOT_LOGO_W == (int)ceil(LW * BOOT_LOGO_U), "strike width == ceil(15.264 u)");
    CHECK(BOOT_LOGO_H == (int)ceil(LH * BOOT_LOGO_U), "strike height == ceil(10.459 u)");
    CHECK(BOOT_LOGO_W <= 256 && BOOT_LOGO_H <= 256, "strike fits the oracle raster");
    /* The placement rule (boot_logo.h header): the mark's centre line on a
     * pixel boundary, the rows centred. */
    ox = floor(MX * BOOT_LOGO_U + 0.5) - MX * BOOT_LOGO_U;
    oy = (BOOT_LOGO_H - LH * BOOT_LOGO_U) / 2.0;

    CHECK(decode_strike(), "RLE decodes to exactly W x H (rows never overrun)");

#ifdef BOOT_LOGO_MUT_NOTCH_ROW
    {
        /* The back block's notch floor (T2 at the mark shift): the first
         * centre-covered row takes the row above it, across the floor span. */
        double top = oy + (LH - (MY + 0.225)) * BOOT_LOGO_U;
        int r = (int)ceil(top - 0.5);
        int x0 = (int)(ox + (MX - 1.0) * BOOT_LOGO_U), x1 = (int)(ox + (MX + 1.0) * BOOT_LOGO_U);
        for (int i = x0; i <= x1; i++) got[r][i] = got[r - 1][i];
        printf("  MUTANT BOOT_LOGO_MUT_NOTCH_ROW: notch floor row %d moved up one\n", r);
    }
#endif

    render_geometry();
    CHECK(near_tie > 1e-6, "no pixel centre within 1e-6 of an edge (no rounding ties)");
    printf("  nearest centre-to-edge distance: %.6f\n", near_tie);

    int diff = 0, shown = 0;
    long n[4] = {0, 0, 0, 0};
    for (int j = 0; j < BOOT_LOGO_H; j++) {
        for (int i = 0; i < BOOT_LOGO_W; i++) {
            n[want[j][i] & 3]++;
            if (want[j][i] != got[j][i]) {
                if (shown++ < 12)
                    printf("  DIFF (%d,%d): strike code %d, geometry code %d\n",
                           i, j, got[j][i], want[j][i]);
                diff++;
            }
        }
    }
    printf("  geometry: %ld clear, %ld top, %ld dark, %ld light; strike %d x %d, %d RLE bytes\n",
           n[0], n[1], n[2], n[3], BOOT_LOGO_W, BOOT_LOGO_H, BOOT_LOGO_RLE_BYTES);
    CHECK(n[1] > 0 && n[2] > 0 && n[3] > 0, "every face role is present");
    CHECK(diff == 0, "strike == geometry, pixel for pixel");
    if (diff) printf("  %d pixels differ\n", diff);

    return TEST_SUMMARY("test-boot-logo");
}
